export function createApp(runtime) {
  let session;
  let lease;
  let pending = Promise.resolve();

  // Host operations are asynchronous: serialize controls, including hangup
  // requested while a connection is still being established.
  function enqueue(operation) {
    const result = pending.then(operation);
    pending = result.catch(() => {});
    return result;
  }

  async function cleanup() {
    const errors = [];
    if (session) {
      try {
        await session.disconnect();
        session = undefined;
      } catch (error) {
        errors.push(error);
      }
    }
    if (lease) {
      try {
        await lease.release();
        lease = undefined;
      } catch (error) {
        errors.push(error);
      }
    }
    // Keep failed resource handles so a later hangup can retry cleanup.
    if (errors.length) throw new AggregateError(errors, 'Call cleanup failed');
  }

  return {
    calls: {
      start(peerId) {
        return enqueue(async () => {
          if (session || lease) throw new Error('A call is already active');
          lease = await runtime.execution.acquire('outgoing-call');
          try {
            session = await runtime.transport.connect(peerId);
          } catch (error) {
            try {
              await cleanup();
            } catch (cleanupError) {
              throw new AggregateError([error, cleanupError], 'Connection and cleanup failed');
            }
            throw error;
          }
        });
      },
      setMuted(value) {
        return enqueue(async () => {
          if (typeof value !== 'boolean') throw new TypeError('Mute value must be a boolean');
          if (!session) throw new Error('No active call');
          await session.setMuted(value);
        });
      },
      end() {
        return enqueue(cleanup);
      },
    },
  };
}

