import test from 'node:test';
import assert from 'node:assert/strict';
import { createApp } from './app.js';
import { createRuntime } from './platform/runtime.js';

test('outgoing call stays active in background, supports mute, and releases resources', async () => {
  const runtime = createRuntime();
  const app = createApp(runtime);
  await app.calls.start('peer');
  runtime.enterBackground();
  assert.deepEqual(runtime.snapshot(), { sessions: 1, leases: 1, audible: true, muted: [false] });
  await app.calls.setMuted(true);
  assert.deepEqual(runtime.snapshot().muted, [true]);
  await app.calls.setMuted(false);
  assert.deepEqual(runtime.snapshot().muted, [false]);
  await app.calls.end();
  assert.deepEqual(runtime.snapshot(), { sessions: 0, leases: 0, audible: false, muted: [] });
  await app.calls.end();
  await app.calls.start('next');
  await app.calls.end();
});

test('connection failure releases the ongoing execution lease', async () => {
  const runtime = createRuntime({ failConnect: true });
  const app = createApp(runtime);
  await assert.rejects(app.calls.start('peer'), /Connection failed/);
  assert.deepEqual(runtime.snapshot(), { sessions: 0, leases: 0, audible: false, muted: [] });
});

test('concurrent starts cannot open two conversations', async () => {
  const runtime = createRuntime();
  const app = createApp(runtime);
  const first = app.calls.start('first');
  const second = app.calls.start('second');
  await first;
  await assert.rejects(second, /already/);
  assert.equal(runtime.snapshot().sessions, 1);
  await app.calls.end();
});

test('hangup during connection waits for and cleans up the pending session', async () => {
  const runtime = createRuntime();
  const connect = runtime.transport.connect;
  let resume;
  const pending = new Promise(resolve => { resume = resolve; });
  runtime.transport.connect = async peer => { await pending; return connect(peer); };
  const app = createApp(runtime);
  const start = app.calls.start('peer');
  const end = app.calls.end();
  resume();
  await Promise.all([start, end]);
  assert.equal(runtime.snapshot().sessions, 0);
  assert.equal(runtime.snapshot().leases, 0);
});

test('invalid mute and idle mute fail without poisoning subsequent operations', async () => {
  const runtime = createRuntime();
  const app = createApp(runtime);
  await assert.rejects(app.calls.setMuted(true), /active/);
  await app.calls.start('peer');
  await assert.rejects(app.calls.setMuted('false'), /boolean/);
  assert.deepEqual(runtime.snapshot().muted, [false]);
  await app.calls.end();
});

test('hangup attempts both cleanups and retains a failed handle for retry', async () => {
  const runtime = createRuntime();
  const connect = runtime.transport.connect;
  let failDisconnect = true;
  runtime.transport.connect = async peer => {
    const session = await connect(peer);
    return {
      ...session,
      async disconnect() {
        if (failDisconnect) throw new Error('Disconnect failed');
        await session.disconnect();
      },
    };
  };
  const app = createApp(runtime);
  await app.calls.start('peer');
  await assert.rejects(app.calls.end(), /cleanup failed/);
  assert.equal(runtime.snapshot().leases, 0);
  await assert.rejects(app.calls.start('next'), /already/);
  failDisconnect = false;
  await app.calls.end();
  assert.equal(runtime.snapshot().sessions, 0);
});

test('failed lease release after connection failure remains retryable', async () => {
  const runtime = createRuntime({ failConnect: true });
  const acquire = runtime.execution.acquire;
  let failRelease = true;
  runtime.execution.acquire = async reason => {
    const lease = await acquire(reason);
    return {
      async release() {
        if (failRelease) throw new Error('Release failed');
        await lease.release();
      },
    };
  };
  const app = createApp(runtime);
  await assert.rejects(app.calls.start('peer'), /Connection and cleanup failed/);
  assert.equal(runtime.snapshot().sessions, 0);
  assert.equal(runtime.snapshot().leases, 1);
  failRelease = false;
  await app.calls.end();
  assert.equal(runtime.snapshot().leases, 0);
});

